from collections import defaultdict
from functools import wraps
from operator import itemgetter

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        access_count = defaultdict(int)
        min_count = [0]
        size = 0

        def get_key(args, kwargs):
            if typed:
                return (func, args, tuple(kwargs.items()))
            return (func, tuple(args), tuple(sorted(kwargs.items())))

        def update_min_count():
            min_count[0] = min(access_count.values() or [0])

        def get(key):
            access_count[key] += 1
            update_min_count()
            return cache[key]

        def set(key, value):
            nonlocal size
            if size >= maxsize:
                lfu_key = min(access_count.items(), key=itemgetter(1))[0]
                del cache[lfu_key]
                del access_count[lfu_key]
                size -= 1
            cache[key] = value
            access_count[key] = 1
            update_min_count()
            size += 1

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = get_key(args, kwargs)
            try:
                return get(key)
            except KeyError:
                value = func(*args, **kwargs)
                set(key, value)
                return value

        return wrapper

    return decorator
