class Histogram:
    def __init__(self, edges):
        self.edges = np.asarray(edges)
        self.values = np.zeros(len(edges) - 1)

    def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        bin_index = np.searchsorted(self.edges, coord, side='right') - 1
        if 0 <= bin_index < len(self.values):
            self.values[bin_index] += weight

    def plot(self, ax=None):
        if ax is None:
            ax = plt.gca()
        ax.bar(self.edges[:-1], self.values, width=np.diff(self.edges), align='edge')
        plt.show()
