import heapq
from collections import defaultdict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.count = 0
        self.cache = {}
        self.freq = defaultdict(list)

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        freq, value = self.cache[key]
        self.freq[freq].remove((key, value))
        heapq.heapify(self.freq[freq])
        self.cache[key] = (freq + 1, value)
        heapq.heappush(self.freq[freq + 1], (key, value))
        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.get(key)
            self.cache[key] = (self.cache[key][0], value)
        else:
            if self.count == self.capacity:
                min_freq = min(self.freq)
                while not self.freq[min_freq]:
                    min_freq += 1
                key_to_remove, _ = heapq.heappop(self.freq[min_freq])
                del self.cache[key_to_remove]
                self.count -= 1
            self.cache[key] = (1, value)
            heapq.heappush(self.freq[1], (key, value))
            self.count += 1

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self.cache:
            raise KeyError('cache is empty')
        min_freq = min(self.freq)
        while not self.freq[min_freq]:
            min_freq += 1
        key, value = heapq.heappop(self.freq[min_freq])
        del self.cache[key]
        self.count -= 1
        return (key, value)
